require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/blockchain.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='verify_all'){$ids=db()->query("SELECT id FROM registrations WHERE status<>'Cancelled'")->fetchAll(PDO::FETCH_COLUMN);$failed=0;foreach($ids as $id)if(!verify_registration((int)$id)['secure'])$failed++;$chainResult=verify_chain(true);flash($failed||!$chainResult['healthy']?'warning':'success','Verification complete: '.$failed.' registration issue(s), '.count($chainResult['breaks']).' chain issue(s).');redirect('admin/integrity_monitor.php');}}$chain=verify_chain(true);$blocks=db()->query("SELECT l.*,r.user_id,r.name,r.reg_no,e.title FROM blockchain_ledger l LEFT JOIN registrations r ON r.id=l.registration_id LEFT JOIN events e ON e.id=r.event_id ORDER BY l.id DESC")->fetchAll();$pageTitle='Integrity monitor';require dirname(__DIR__).'/includes/header.php';
?>
<div class="d-flex justify-content-between align-items-end mb-4"><div><p class="text-primary text-uppercase small fw-bold mb-1">Blockchain ledger</p><h1 class="h2 fw-bold">Integrity monitor</h1></div><div class="d-flex gap-2"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="verify_all"><button class="btn btn-primary">Verify all</button></form><a class="btn btn-outline-primary" href="<?=e(url('admin/integrity_failures.php'))?>">Open failures</a></div></div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="card p-3"><span class="small text-secondary">Chain health</span><div class="h4 mt-1 <?=$chain['healthy']?'text-success':'text-danger'?>"><?=$chain['healthy']?'Healthy':'Break detected'?></div></div></div><div class="col-md-4"><div class="card p-3"><span class="small text-secondary">Total blocks</span><div class="metric"><?=$chain['count']?></div></div></div><div class="col-md-4"><div class="card p-3"><span class="small text-secondary">Chain issues</span><div class="metric"><?=count($chain['breaks'])?></div></div></div></div>
<div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Block</th><th>Registration</th><th>Data hash</th><th>Previous hash</th><th>Timestamp</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($blocks as $b):$valid=!in_array((int)$b['id'],$chain['breaks'],true);if($b['registration_id'])$valid=$valid&&verify_registration((int)$b['registration_id'],false)['secure'];?><tr><td>#<?=(int)$b['id']?></td><td><?php if($b['registration_id']):?>#<?=e((string)$b['registration_id'])?> · <?=e($b['name']??'')?> <div class="small text-secondary"><?=e($b['title']??'')?></div><?php else:?>Genesis<?php endif;?></td><td><code><?=e(substr($b['data_hash'],0,14))?>…</code></td><td><code><?=e(substr($b['previous_hash'],0,14))?>…</code></td><td><?=e(date('M j, Y H:i',strtotime($b['created_at'])))?></td><td><span class="badge <?=$valid?'text-bg-success':'text-bg-danger'?>"><?=$valid?'Secure':'Tampered'?></span></td><td><?php if($b['registration_id']):?><a href="<?=e(url('admin/verify.php?id='.(int)$b['registration_id']))?>">Inspect</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
